"use client";

import { useState } from "react";
import {
    History,
    FileText,
    Plus,
    X,
    Search,
    Upload,
    ChevronDown,
    Save,
    Pill,
    Loader2,
    CheckCircle2
} from "lucide-react";
import { useData } from "@/lib/hooks";

export default function PurchasesPage() {
    const [showForm, setShowForm] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const { data: suppliers } = useData<any[]>("/api/suppliers");
    const { data: products } = useData<any[]>("/api/products");
    const { data: purchaseHistory, refetch: refetchHistory } = useData<any[]>("/api/purchases");

    const [formItems, setFormItems] = useState<any[]>([]);

    const handleSavePurchase = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSubmitting(true);
        const formData = new FormData(e.currentTarget);
        const data = {
            supplierId: formData.get("supplierId"),
            invoiceNo: formData.get("invoiceNo"),
            date: formData.get("date"),
            items: formItems
        };

        try {
            const res = await fetch("/api/purchases", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(data)
            });
            if (res.ok) {
                setShowForm(false);
                setFormItems([]);
                refetchHistory();
            }
        } catch (err) {
            console.error(err);
        } finally {
            setIsSubmitting(false);
        }
    };

    const addItem = () => {
        setFormItems([...formItems, { productId: "", batchNo: "", expiryDate: "", quantity: 0, purchasePrice: 0 }]);
    };

    return (
        <>
            <div className="flex flex-col gap-8 animate-fade-in-up">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">Purchase Entry</h1>
                        <p className="text-gray-500 mt-1">Record new inventory shipments and AI-scan invoices.</p>
                    </div>
                    <button
                        onClick={() => setShowForm(true)}
                        className="btn-primary flex items-center gap-2"
                    >
                        <Plus className="h-4 w-4" />
                        New Purchase Record
                    </button>
                </div>

                {/* Purchase History */}
                <div className="card-premium rounded-2xl overflow-hidden">
                    <div className="p-6 border-b border-gray-100 flex items-center gap-2">
                        <History className="h-5 w-5 text-purple-600" />
                        <h3 className="text-lg font-bold text-gray-900">Recent Purchases</h3>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="text-left py-4 px-6 text-sm font-bold text-gray-500">Invoice #</th>
                                    <th className="text-left py-4 px-6 text-sm font-bold text-gray-500">Supplier</th>
                                    <th className="text-left py-4 px-6 text-sm font-bold text-gray-500">Date</th>
                                    <th className="text-left py-4 px-6 text-sm font-bold text-gray-500">Items</th>
                                    <th className="text-left py-4 px-6 text-sm font-bold text-gray-500">Total Price</th>
                                </tr>
                            </thead>
                            <tbody>
                                {purchaseHistory?.map((p: any) => (
                                    <tr key={p.id} className="border-b border-gray-50">
                                        <td className="py-4 px-6 font-medium text-gray-900">{p.invoiceNo}</td>
                                        <td className="py-4 px-6 text-gray-600">{p.supplier.name}</td>
                                        <td className="py-4 px-6 text-gray-600">{new Date(p.date).toLocaleDateString()}</td>
                                        <td className="py-4 px-6 text-gray-600">{p.items.length}</td>
                                        <td className="py-4 px-6 font-bold text-gray-900">PKR {p.total.toLocaleString()}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

            </div>

            <PurchaseModal
                showForm={showForm}
                setShowForm={setShowForm}
                handleSavePurchase={handleSavePurchase}
                suppliers={suppliers}
                products={products}
                formItems={formItems}
                setFormItems={setFormItems}
                addItem={addItem}
                isSubmitting={isSubmitting}
            />
        </>
    );
}

function PurchaseModal({
    showForm,
    setShowForm,
    handleSavePurchase,
    suppliers,
    products,
    formItems,
    setFormItems,
    addItem,
    isSubmitting
}: any) {
    return (
        <>
            {/* Add Purchase Modal */}
            {showForm && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4 overflow-y-auto">
                    <div className="bg-white rounded-3xl w-full max-w-4xl max-h-[90vh] overflow-y-auto animate-fade-in-up shadow-2xl">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white z-10">
                            <h2 className="text-2xl font-bold text-gray-900">New Purchase Record</h2>
                            <button onClick={() => setShowForm(false)} className="p-2 hover:bg-gray-100 rounded-full"><X className="h-5 w-5" /></button>
                        </div>
                        <form onSubmit={handleSavePurchase} className="p-8">
                            <div className="grid md:grid-cols-3 gap-6 mb-8">
                                <div>
                                    <label className="text-sm font-bold text-gray-700">Supplier</label>
                                    <select name="supplierId" required className="w-full h-12 border rounded-xl px-4 mt-2">
                                        <option value="">Select Supplier</option>
                                        {suppliers?.map((s: any) => <option key={s.id} value={s.id}>{s.name}</option>)}
                                    </select>
                                </div>
                                <div>
                                    <label className="text-sm font-bold text-gray-700">Invoice No</label>
                                    <input name="invoiceNo" required className="w-full h-12 border rounded-xl px-4 mt-2" />
                                </div>
                                <div>
                                    <label className="text-sm font-bold text-gray-700">Purchase Date</label>
                                    <input name="date" type="date" required className="w-full h-12 border rounded-xl px-4 mt-2" defaultValue={new Date().toISOString().split('T')[0]} />
                                </div>
                            </div>

                            <div className="border rounded-2xl overflow-hidden mb-6">
                                <table className="w-full">
                                    <thead className="bg-gray-50">
                                        <tr>
                                            <th className="py-3 px-4 text-left text-xs font-bold text-gray-500">Medicine</th>
                                            <th className="py-3 px-4 text-left text-xs font-bold text-gray-500">Batch</th>
                                            <th className="py-3 px-4 text-left text-xs font-bold text-gray-500">Expiry</th>
                                            <th className="py-3 px-4 text-left text-xs font-bold text-gray-500">Qty</th>
                                            <th className="py-3 px-4 text-left text-xs font-bold text-gray-500">PKR</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {formItems.map((item: any, idx: number) => (
                                            <tr key={idx} className="border-t">
                                                <td className="p-2">
                                                    <select
                                                        value={item.productId}
                                                        onChange={(e) => {
                                                            const newItems = [...formItems];
                                                            newItems[idx].productId = e.target.value;
                                                            setFormItems(newItems);
                                                        }}
                                                        className="w-full h-10 border rounded-lg px-2 text-sm"
                                                    >
                                                        <option value="">Select</option>
                                                        {products?.map((p: any) => <option key={p.id} value={p.id}>{p.name}</option>)}
                                                    </select>
                                                </td>
                                                <td className="p-2"><input value={item.batchNo} onChange={(e) => { const n = [...formItems]; n[idx].batchNo = e.target.value; setFormItems(n); }} className="w-full h-10 border rounded-lg px-2 text-sm" /></td>
                                                <td className="p-2"><input type="date" value={item.expiryDate} onChange={(e) => { const n = [...formItems]; n[idx].expiryDate = e.target.value; setFormItems(n); }} className="w-full h-10 border rounded-lg px-2 text-sm" /></td>
                                                <td className="p-2 w-20"><input type="number" value={item.quantity} onChange={(e) => { const n = [...formItems]; n[idx].quantity = e.target.value; setFormItems(n); }} className="w-full h-10 border rounded-lg px-2 text-sm" /></td>
                                                <td className="p-2 w-24"><input type="number" value={item.purchasePrice} onChange={(e) => { const n = [...formItems]; n[idx].purchasePrice = e.target.value; setFormItems(n); }} className="w-full h-10 border rounded-lg px-2 text-sm" /></td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                                <button type="button" onClick={addItem} className="w-full py-4 text-purple-600 font-bold text-sm bg-purple-50 hover:bg-purple-100 transition-colors">
                                    + Add Item to Invoice
                                </button>
                            </div>

                            <div className="flex gap-4">
                                <button type="button" onClick={() => setShowForm(false)} className="flex-1 py-4 border rounded-2xl font-bold">Cancel</button>
                                <button disabled={isSubmitting} type="submit" className="flex-1 py-4 bg-purple-600 text-white rounded-2xl font-bold shadow-lg shadow-purple-500/20">
                                    {isSubmitting ? "Saving..." : "Record Purchase Shipment"}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </>
    );
}
